            // TODO API_TEST_START
            net.coobird.thumbnailator.filters.ImageFilter dummyFilter1 = new net.coobird.thumbnailator.filters.ImageFilter() {
                @Override
                public java.awt.image.BufferedImage apply(java.awt.image.BufferedImage img) {
                    return img;
                }
            };

            net.coobird.thumbnailator.filters.ImageFilter dummyFilter2 = new net.coobird.thumbnailator.filters.ImageFilter() {
                @Override
                public java.awt.image.BufferedImage apply(java.awt.image.BufferedImage img) {
                    return img;
                }
            };

            net.coobird.thumbnailator.filters.Pipeline pipeline = new net.coobird.thumbnailator.filters.Pipeline();
            pipeline.addAll(java.util.Arrays.asList(dummyFilter1, dummyFilter2));

            java.util.List<net.coobird.thumbnailator.filters.ImageFilter> resultFilters = pipeline.getFilters();

            assert resultFilters != null && resultFilters.size() == 2 : "Pipeline should contain exactly 2 filters after addAll";
            assert resultFilters.get(0) == dummyFilter1 : "First filter should match the first added filter";
            assert resultFilters.get(1) == dummyFilter2 : "Second filter should match the second added filter";

            java.awt.image.BufferedImage resultImage = pipeline.apply(sourceImage);
            assert resultImage == sourceImage : "Pipeline of identity filters should return the original image instance";

            System.out.println("__CHECK__ addAll " + resultFilters.size());
            // TODO API_TEST_END
            System.out.println("__DONE__");
        } catch (Throwable exc) {
            System.err.println("__RUN_ERR__ " + exc.getClass().getSimpleName()
                    + ": " + exc.getMessage());
            exc.printStackTrace(System.err);
            System.exit(1);
        }
    }
}
